func TestImport_RuleSegments(t *testing.T) {
	tests := []struct {
		name         string
		segment      string
		wantKey      string
		wantKeys     []string
		wantOperator flipt.SegmentOperator
		wantError    string
	}{
		{
			name:         "string",
			segment:      "segment1",
			wantKey:      "segment1",
			wantOperator: flipt.SegmentOperator_OR_SEGMENT_OPERATOR,
		},
		{
			name:         "one key object uses OR",
			segment:      "{keys: [segment1], operator: AND_SEGMENT_OPERATOR}",
			wantKey:      "segment1",
			wantOperator: flipt.SegmentOperator_OR_SEGMENT_OPERATOR,
		},
		{
			name:         "two key object uses AND",
			segment:      "{keys: [segment1, segment2], operator: AND_SEGMENT_OPERATOR}",
			wantKeys:     []string{"segment1", "segment2"},
			wantOperator: flipt.SegmentOperator_AND_SEGMENT_OPERATOR,
		},
		{
			name:      "missing segment",
			wantError: "must have a segment",
		},
		{
			name:      "unknown operator for multiple keys",
			segment:   "{keys: [segment1, segment2], operator: UNKNOWN}",
			wantError: "unsupported operator",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			var doc string
			if tc.segment == "" {
				doc = "flags:\n  - key: flag1\n    rules:\n      - rank: 1\n"
			} else {
				doc = "flags:\n  - key: flag1\n    rules:\n      - segment: " + tc.segment + "\n"
			}
			creator := &mockCreator{}
			err := NewImporter(creator).Import(context.Background(), strings.NewReader(doc))
			if tc.wantError != "" {
				require.ErrorContains(t, err, tc.wantError)
				return
			}
			require.NoError(t, err)
			require.Len(t, creator.ruleReqs, 1)
			assert.Equal(t, tc.wantKey, creator.ruleReqs[0].SegmentKey)
			assert.Equal(t, tc.wantKeys, creator.ruleReqs[0].SegmentKeys)
			assert.Equal(t, tc.wantOperator, creator.ruleReqs[0].SegmentOperator)
		})
	}
}

