package cue

import (
	_ "embed"
	"errors"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerrors "cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error is a collection of fields that represent positions in files where the user
// has made some kind of error.
type Error struct {
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Result is a collection of errors that occurred during validation.
type Result struct {
	Errors []Error `json:"errors"`
}

type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil {
		return nil, v.Err()
	}

	return &FeaturesValidator{
		cue: cctx,
		v:   v,
	}, nil
}

// Validate validates a YAML file against our cue definition of features.
func (v FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	var result Result

	f, err := yaml.Extract("", b)
	if err != nil {
		return result, err
	}

	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil {
		return Result{}, err
	}

	err = v.v.
		Unify(yv).
		Validate(cue.All(), cue.Concrete(true))

	for _, e := range cueerrors.Errors(err) {
		rerr := Error{
			Message: e.Error(),
			Location: Location{
				File: file,
			},
		}

		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			rerr.Location.Line = p.Line()
			rerr.Location.Column = p.Column()
		}

		result.Errors = append(result.Errors, rerr)
	}

	if len(result.Errors) > 0 {
		return result, ErrValidationFailed
	}

	return result, nil
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"

	"github.com/spf13/cobra"
	"go.flipt.io/flipt/internal/cue"
)

type validateCommand struct {
	issueExitCode int
	format        string
}

const (
	jsonFormat = "json"
	textFormat = "text"
)

func newValidateCommand() *cobra.Command {
	v := &validateCommand{}

	cmd := &cobra.Command{
		Use:   "validate",
		Short: "Validate flipt flag state (.yaml, .yml) files",
		Run:   v.run,
	}

	cmd.Flags().IntVar(&v.issueExitCode, "issue-exit-code", 1, "Exit code to use when issues are found")

	cmd.Flags().StringVarP(
		&v.format,
		"format", "F",
		"text",
		"output format: json, text",
	)

	return cmd
}

func (v *validateCommand) run(cmd *cobra.Command, args []string) {
	validator, err := cue.NewFeaturesValidator()
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	for _, arg := range args {
		f, err := os.ReadFile(arg)
		if err != nil {
			fmt.Println(err)
			os.Exit(1)
		}

		res, err := validator.Validate(arg, f)
		if err != nil && !errors.Is(err, cue.ErrValidationFailed) {
			fmt.Println(err)
			os.Exit(1)
		}

		if len(res.Errors) > 0 {
			if v.format == jsonFormat {
				if err := json.NewEncoder(os.Stdout).Encode(res); err != nil {
					fmt.Println(err)
					os.Exit(1)
				}
				os.Exit(v.issueExitCode)
				return
			}

			fmt.Println("Validation failed!")

			for _, e := range res.Errors {
				fmt.Printf(
					`
- Message  : %s
  File     : %s
  Line     : %d
  Column   : %d
`, e.Message, e.Location.File, e.Location.Line, e.Location.Column)
			}

			os.Exit(v.issueExitCode)
		}
	}
}
